from audit_utils import *

for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/212.tex'
 def r(a,b,line,kind='reading',why='',count=1):
  replace(rel,a,b,layer,'212-108',line,'4; Proposition 4.1','400-dpi full scan and all three enlarged bands. '+why,kind,count=count)
 r(r'v(0)=0,',r'v(0)=0','first display end',why='There is no comma after the last zero.')
 r(r'\Delta_m\amalg_{\Delta_0}\Delta_n',r'\Delta_m\mathbin{\mathrm{n}}_{\Delta_0}\Delta_n','pushout display',why='The operator printed between the two simplices has the literal shape of an upright lower-case n. This local typed glyph is retained in both layers as notation for the explicitly named amalgamated sum; it is not silently replaced by a modern amalgam sign.')
 for term in ['objet simplicial','semi-simplicial','opérations\nde symétrie','catégories','groupoïdes']:
  r(r'\emph{'+term+'}',r'\uline{'+term+'}','emphasis: '+term.replace('\n',' '),why='The phrase has a straight underline in the scan.')
 r('i.e.','i. e.','two abbreviations',count=2,why='The abbreviation is printed with a space.')
 r('ensembles, i. e. un ensemble simplicial (resp. semi-simplicial), dit',r'ensembles, i. e. un \uline{ensemble simplicial} (resp. \uline{semi-simplicial}), dit','definition of the associated nerves',why='The print underlines ensemble simplicial and semi-simplicial here as well as in the earlier definition.')
 r(r'\emph{associé à la catégorie $Z$}:',r'\uline{associé à la catégorie} $Z$ :','associated nerve name',why='Only the prose is straight-underlined; Z is not. The colon is spaced.')
 r(r"de la catégorie $\mathcal S$ (resp. $\mathcal S'$) dans la catégorie des",r"de la catégorie $\mathcal S$, (resp. $\mathcal S'$), dans la catégorie des",'Hom functor sentence',why='The printed parenthesis has a comma on each side.')
 r('Ceci posé:', 'Ceci posé :','proposition introduction',why='The colon is spaced.')
 r(r'\longmapsto',r'\rightsquigarrow','two nerve functors',count=2,why='Both printed association arrows have a wavy shaft.')
 r("qui transforment les sommes\namalgamées $A\\amalg_C B$ du type précisé plus haut, en produits fibrés\nd'ensembles.",r'''\uline{qui transforment les sommes amalgamées} $A\amalg_C B$ \uline{du type précisé plus haut, en produits fibrés d'ensembles}.''','Proposition 4.1, exactness condition',why='The entire verbal condition is straight-underlined on either side of the formula, excluding the final period.')
 r(r'A\amalg_C B',r'A\mathbin{\phantom{\mathrm{n}}}_C B','Proposition 4.1, amalgamated sum',why='The print has A and B with a lowered C between them, but no visible operator above C. Both layers first restore this omission.')
 if tree=='fr':
  r(r'A\mathbin{\phantom{\mathrm{n}}}_C B',r'A\mathbin{\mathrm{n}}_C B','Proposition 4.1, amalgamated sum',kind='misprint of the original',why='Supply the absent amalgamated-sum operator, in the same n-shaped notation used in the display above. The sentence specifies exactly that pushout and its maps; the lowered base C alone is incomplete notation.')
 s,_,_=page_text(rel,108)
 for old,new in [(r'\mathcal C',r'\text{\uwave{C}}'),(r'\mathcal S',r'\text{\uwave{S}}')]:
  r(old,new,'category alphabet',count=s.count(old),why='Category letters have wavy underlines.')
 upright_page(rel,layer,'212-108')

event('212-4-ordered-colimits','targeted proof check','No two nonempty total orders have a coproduct in the category of nonempty finite total orders: for any putative structure maps, choose one element from each summand; their images are comparable, whereas the two pairs of constant maps to [0,1], with values (0,1) and (1,0), require both opposite strict comparisons. For the stated pushout counterexample with both singleton maps selecting the same endpoint of [0,1], the two unglued endpoints can likewise map to 0 and 1 in either order while the common endpoint has the requisite fixed value; this contradicts either comparison in a proposed total-order pushout. In the special terminal-to-initial gluing, concatenate the chains, identifying m in [0,m] with 0 in [0,n]; every compatible pair of increasing maps extends uniquely to [0,m+n].','212, p. 108, first paragraph and two displays')
event('212-4-nerve-comparison','targeted proof check','The chaotic category on [0,n] has exactly one arrow between every ordered pair and all arrows invertible; the ordered category has the unique arrow i to j for i at most j. Restricting functors along the ordered-to-chaotic inclusion gives Z prime to Z double-prime. Its image consists exactly of chains of isomorphisms: extension is unique because reverse arrows must be inverses and long arrows composites. Thus this map is bijective in every degree when Z is a groupoid, and surjectivity in degree one already forces every arrow of Z to be invertible. Precomposition is contravariant, as required by the definitions; the local abbreviated word foncteur is not expanded in the editions.','212, p. 108, paragraph before Proposition 4.1')
event('212-4.1','independent re-proof','Category half: for a contravariant K on S prime carrying endpoint amalgamations to pullbacks, put objects K0 and arrows K1, with endpoints induced by the two vertex inclusions. The unique map [0,1] to [0,0] gives identities. The pullback isomorphism K2 = K1 times_K0 K1 defines composition by the edge inclusion 0,1 mapped to 0,2. The two ways of composing a triple are equal by functoriality from K3, and the two degeneracies of K2 give the unit laws. Repeated endpoint amalgamation identifies Kn with composable n-tuples, yielding an isomorphism with the nerve. Conversely any category has these tuple descriptions, so its nerve preserves the specified amalgamations. A natural map of nerves is determined in degrees zero and one and, by compatibility with the degree-two maps and degeneracy, is precisely a functor. This proves full faithfulness and the asserted essential image for categories. The groupoid half continues on the next page.','212, p. 108, Proposition 4.1, category half')
record_page('212',108,r'''Compared sources/fr_printed/fr/212.tex and sources/fr/fr/212.tex entry lines 414–463 with scan leaf 11 at 400 dpi, full page and all three enlarged bands. Inspected the endpoint maps, every simplex subscript and prime, the two amalgamated-sum expressions, nerve arrows, underlining and proposition number.

Both layers restore the unpunctuated first display, straight emphasis, wavy category symbols and association arrows, spaced abbreviations, printed commas and upright letters. The display's n-shaped amalgamated-sum operator is retained as a local typographic notation in both layers. The later formula in Proposition 4.1 visibly lacks its operator: the printed layer keeps the blank above C; the corrected layer supplies the same n-shaped operator. That omission is the sole mathematical difference between the layers on this page.

Verified the nonexistence examples for ordered colimits and the concatenation pushout. Checked the comparison between the two nerves and independently reconstructed the category half of Proposition 4.1 from the specified pullback identities, including full faithfulness. The historical names simplicial and semi-simplicial are retained exactly as defined here.''')
